 mindmap:{center:"Decorators",branches:[{t:"What @ means",kids:["f = d(f)","runs once, at definition"]},{t:"The wrapper",kids:["may call func","may call it twice","may never call it"]},{t:"Stacking",kids:["bottom one first","outer wraps inner"]},{t:"Exam questions",kids:["predict the output","order of prints"]}]},
